using System;
using System.Linq;
using Enterprise.DbUpgrader.Transformation.Common;

namespace Enterprise.DbUpgrader.Transformations.Transforms.Architecture
{
	class ChangeLoggingMethodToElasticSearchLoggingInSANDEnvironments : RegistryDataTransformation
	{
		public override string UserDescription => "Update to use new service task logging method in internal UAT environments";

		protected override void OfflinePostUpgradeTransform()
		{
			if (!(manager.IsUATSystem ?? false))
			{
				ShowInfo("Not a UAT environment, skipping.");
				return;
			}

			UpdateOrCreateDatabaseValue("LoggingMethods", null, null, "BIN", false, GenerateValue(), null, false, false);
		}

		static byte[] GenerateValue()
		{
			const string value = "";
			var result = Enumerable
				.Range(0, value.Length / 2)
				.Select(i => Convert.ToByte(value.Substring(i << 1, 2), 16))
				.ToArray();
			return result;
		}
	}
}
